function LeafDeco({ style }) {
  return (
    <svg width="60" height="40" viewBox="0 0 60 40" fill="none" style={style}>
      <path d="M5 35 Q20 5 55 8 Q30 15 5 35Z" fill={C.green} opacity="0.15" />
      <path d="M5 35 Q20 5 55 8" stroke={C.green} strokeWidth="1" opacity="0.2" fill="none" />
    </svg>
  );
}

function SunDeco({ style }) {
  return (
    <svg width="50" height="50" viewBox="0 0 50 50" fill="none" style={style}>
      <circle cx="25" cy="25" r="10" fill={C.gold} opacity="0.2" />
      {[0,45,90,135,180,225,270,315].map((angle, i) => (
        <line key={i}
          x1={25 + 13 * Math.cos(angle * Math.PI / 180)}
          y1={25 + 13 * Math.sin(angle * Math.PI / 180)}
          x2={25 + 20 * Math.cos(angle * Math.PI / 180)}
          y2={25 + 20 * Math.sin(angle * Math.PI / 180)}
          stroke={C.gold} strokeWidth="1.5" strokeLinecap="round" opacity="0.25"
        />
      ))}
    </svg>
  );
}

function DropletIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
      <path d="M12 2.69l5.66 5.66a8 8 0 11-11.31 0z" stroke={C.gold} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" fill={C.goldLight} />
    </svg>
  );
}

function Pill({ label, selected, onClick }) {
  return (
    <button onClick={onClick} style={{
      background: selected ? C.goldLight : "transparent",
      border: `1px solid ${selected ? C.gold : C.sand}`,
      borderRadius: 999,
      padding: "7px 16px",
      fontSize: 13,
      color: selected ? C.goldText : C.mutedText,
      cursor: "pointer",
      transition: "all 0.2s",
      margin: "0 6px 8px 0",
      fontFamily: "Georgia, serif",
      letterSpacing: "0.01em",
    }}>{label}</button>
  );
}

function ScaleRow({ max, value, onChange }) {
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 6 }}>
      {Array.from({ length: max }, (_, i) => i + (max === 10 ? 0 : 1)).map(n => (
        <button key={n} onClick={() => onChange(String(n))} style={{
          width: 38, height: 38,
          background: value === String(n) ? C.gold : C.cream,
          border: `1px solid ${value === String(n) ? C.gold : C.sand}`,
          borderRadius: 8,
          fontSize: 13,
          color: value === String(n) ? "white" : C.mutedText,
          cursor: "pointer",
          transition: "all 0.2s",
          fontFamily: "Georgia, serif",
          fontWeight: value === String(n) ? "500" : "400",
        }}>{n}</button>
      ))}
    </div>
  );
}


function SectionBadge({ name }) {
  const icon = sectionIcons[name] || sectionIcons["Profil"];
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: "1rem" }}>
      <div style={{ width: 28, height: 28, borderRadius: "50%", background: C.greenLight, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={C.green} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
          <path d={icon} />
        </svg>
      </div>
      <span style={{ fontSize: 11, fontWeight: 500, letterSpacing: "0.1em", textTransform: "uppercase", color: C.green, fontFamily: "Georgia, serif" }}>{name}</span>
    </div>
  );
}

function SurveyForm({ onSubmit }) {
  const [answers, setAnswers] = useState({});
  const [step, setStep] = useState(0);
  const [submitted, setSubmitted] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const sections = [...new Set(QUESTIONS.map(q => q.section))];
  const currentSection = sections[step];
  const sectionQs = QUESTIONS.filter(q => q.section === currentSection);
  const isLast = step === sections.length - 1;
  const progress = Math.round((step / sections.length) * 100);

  function setAnswer(id, val) { setAnswers(prev => ({ ...prev, [id]: val })); }
  function toggleMulti(id, val) {
    setAnswers(prev => {
      const arr = prev[id] || [];
      return { ...prev, [id]: arr.includes(val) ? arr.filter(v => v !== val) : [...arr, val] };
    });
  }

  async function handleSubmit() {
    setSubmitting(true);
    await onSubmit({ ...answers, _date: new Date().toISOString() });
    setSubmitting(false);
    setSubmitted(true);
  }

  if (submitted) return (
    <div style={{ textAlign: "center", padding: "3rem 1rem", position: "relative" }}>
      <LeafDeco style={{ position: "absolute", top: 10, left: 0, transform: "rotate(20deg)" }} />
      <LeafDeco style={{ position: "absolute", top: 10, right: 0, transform: "rotate(-160deg) scaleX(-1)" }} />
      <div style={{ width: 60, height: 60, borderRadius: "50%", background: C.greenLight, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 1.25rem" }}>
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke={C.green} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M20 6L9 17l-5-5" />
        </svg>
      </div>
      <h2 style={{ fontSize: 22, fontWeight: 400, fontFamily: "Georgia, serif", color: C.darkText, marginBottom: 10 }}>Merci pour votre retour !</h2>
      <p style={{ fontSize: 14, color: C.mutedText, lineHeight: 1.6 }}>Votre avis aide OFI à perfectionner<br />son huile de figue de barbarie 100% bio.</p>
      <div style={{ display: "flex", justifyContent: "center", gap: 6, marginTop: 20 }}>
        {[1,2,3].map(i => <div key={i} style={{ width: 6, height: 6, borderRadius: "50%", background: i === 2 ? C.gold : C.sand }} />)}
      </div>
    </div>
  );

  return (
    <div style={{ maxWidth: 580, margin: "0 auto", padding: "0 0 2rem" }}>

      <div style={{ position: "relative", overflow: "hidden", background: C.green, borderRadius: "0 0 28px 28px", marginBottom: "1.5rem" }}>
        <LeafDeco style={{ position: "absolute", top: -5, left: -10, opacity: 0.3, transform: "scale(2) rotate(10deg)" }} />
        <LeafDeco style={{ position: "absolute", top: 20, left: 30, opacity: 0.2, transform: "scale(1.2) rotate(40deg)" }} />
        <SunDeco style={{ position: "absolute", top: 12, left: "50%", opacity: 0.25, transform: "translateX(-50%)" }} />

        <div style={{ display: "flex", alignItems: "flex-end", gap: 0, minHeight: 240 }}>
          <div style={{ flex: 1, padding: "2rem 1.25rem 1.5rem", position: "relative", zIndex: 2 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
              <div style={{ width: 28, height: 28, borderRadius: "50%", background: "rgba(255,255,255,0.15)", display: "flex", alignItems: "center", justifyContent: "center" }}>
                <DropletIcon />
              </div>
              <span style={{ fontSize: 11, fontWeight: 500, letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.65)", fontFamily: "Georgia, serif" }}>OFI</span>
            </div>
            <h1 style={{ fontSize: 19, fontWeight: 400, fontFamily: "Georgia, serif", color: "white", lineHeight: 1.4, marginBottom: 10 }}>
              Votre avis sur<br />notre <span style={{ color: C.goldMid, fontStyle: "italic" }}>huile de<br />figue de barbarie</span>
            </h1>
            <p style={{ fontSize: 11, color: "rgba(255,255,255,0.55)", letterSpacing: "0.05em", lineHeight: 1.7 }}>Doré par le soleil d'Israël<br />100% Bio · 2 minutes</p>

          </div>

          <div style={{ width: 160, flexShrink: 0, position: "relative", alignSelf: "flex-end" }}>
            <img
              src="data:image/png;base64,"
              alt="Fiole OFI huile de figue de barbarie"
              style={{ width: "100%", height: 240, objectFit: "cover", objectPosition: "60% center", display: "block", borderRadius: "0 0 28px 0" }}
            />
            <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to right, rgba(74,103,65,0.6) 0%, rgba(74,103,65,0) 60%)", borderRadius: "0 0 28px 0" }} />
          </div>
        </div>
      </div>

      <div style={{ padding: "0 0.25rem" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: "1.25rem" }}>
          <div style={{ flex: 1, height: 3, background: C.sand, borderRadius: 999, overflow: "hidden" }}>
            <div style={{ height: "100%", width: progress + "%", background: `linear-gradient(90deg, ${C.greenMid}, ${C.gold})`, borderRadius: 999, transition: "width 0.5s ease" }} />
          </div>
          <span style={{ fontSize: 11, color: C.mutedText, minWidth: 32, textAlign: "right" }}>{step + 1}/{sections.length}</span>
        </div>

        <SectionBadge name={currentSection} />

        {sectionQs.map((q) => (
          <div key={q.id} style={{
            background: "white",
            border: `1px solid ${C.sand}`,
            borderRadius: 14,
            padding: "1.1rem 1.25rem",
            marginBottom: 10,
            position: "relative",
            overflow: "hidden",
          }}>
            <div style={{ position: "absolute", top: 0, left: 0, width: 3, height: "100%", background: `linear-gradient(180deg, ${C.green}, ${C.gold})`, borderRadius: "3px 0 0 3px" }} />
            <div style={{ paddingLeft: 8 }}>
              <div style={{ fontSize: 11, color: C.goldText, marginBottom: 5, fontFamily: "Georgia, serif", opacity: 0.7 }}>Q{QUESTIONS.indexOf(q) + 1}</div>
              <div style={{ fontSize: 14, fontWeight: 500, marginBottom: 11, lineHeight: 1.5, color: C.darkText, fontFamily: "Georgia, serif" }}>{q.text}</div>

              {q.type === "single" && (
                <div style={{ display: "flex", flexWrap: "wrap" }}>
                  {q.options.map(o => <Pill key={o} label={o} selected={answers[q.id] === o} onClick={() => setAnswer(q.id, o)} />)}
                </div>
              )}
              {q.type === "multi" && (
                <div style={{ display: "flex", flexWrap: "wrap" }}>
                  {q.options.map(o => <Pill key={o} label={o} selected={(answers[q.id] || []).includes(o)} onClick={() => toggleMulti(q.id, o)} />)}
                </div>
              )}
              {q.type === "scale5" && (
                <>
                  <ScaleRow max={5} value={answers[q.id]} onChange={v => setAnswer(q.id, v)} />
                  <div style={{ display: "flex", justifyContent: "space-between", marginTop: 5 }}>
                    <span style={{ fontSize: 11, color: C.mutedText, fontFamily: "Georgia, serif" }}>Médiocre</span>
                    <span style={{ fontSize: 11, color: C.mutedText, fontFamily: "Georgia, serif" }}>Excellent</span>
                  </div>
                </>
              )}
              {q.type === "scale10" && (
                <>
                  <ScaleRow max={10} value={answers[q.id]} onChange={v => setAnswer(q.id, v)} />
                  <div style={{ display: "flex", justifyContent: "space-between", marginTop: 5 }}>
                    <span style={{ fontSize: 11, color: C.mutedText, fontFamily: "Georgia, serif" }}>Jamais</span>
                    <span style={{ fontSize: 11, color: C.mutedText, fontFamily: "Georgia, serif" }}>Certainement</span>
                  </div>
                </>
              )}
              {q.type === "text" && (
                <textarea
                  value={answers[q.id] || ""}
                  onChange={e => setAnswer(q.id, e.target.value)}
                  placeholder="Votre réponse..."
                  style={{ width: "100%", border: `1px solid ${C.sand}`, borderRadius: 8, padding: "8px 12px", fontSize: 13, fontFamily: "Georgia, serif", color: C.darkText, background: C.cream, resize: "none", minHeight: 72, outline: "none", boxSizing: "border-box", lineHeight: 1.6 }}
                />
              )}
              {q.type === "input" && (
                <input
                  type={q.inputType}
                  value={answers[q.id] || ""}
                  onChange={e => setAnswer(q.id, e.target.value)}
                  placeholder={q.placeholder}
                  style={{ width: "100%", border: `1px solid ${C.sand}`, borderRadius: 8, padding: "10px 14px", fontSize: 14, fontFamily: "Georgia, serif", color: C.darkText, background: C.cream, outline: "none", boxSizing: "border-box" }}
                />
              )}
            </div>
          </div>
        ))}

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "1.25rem" }}>
          {step > 0 ? (
            <button onClick={() => setStep(s => s - 1)} style={{ background: "transparent", border: `1px solid ${C.sand}`, borderRadius: 10, padding: "10px 20px", fontSize: 13, color: C.mutedText, cursor: "pointer", fontFamily: "Georgia, serif" }}>← Retour</button>
          ) : <div />}
          {!isLast ? (
            <button onClick={() => setStep(s => s + 1)} style={{ background: C.green, border: "none", borderRadius: 10, padding: "11px 28px", fontSize: 14, fontWeight: 500, color: "white", cursor: "pointer", fontFamily: "Georgia, serif", letterSpacing: "0.02em" }}>Continuer →</button>
          ) : (
            <button onClick={handleSubmit} disabled={submitting} style={{ background: `linear-gradient(135deg, ${C.green}, ${C.gold})`, border: "none", borderRadius: 10, padding: "11px 28px", fontSize: 14, fontWeight: 500, color: "white", cursor: submitting ? "not-allowed" : "pointer", opacity: submitting ? 0.7 : 1, fontFamily: "Georgia, serif", letterSpacing: "0.02em" }}>
              {submitting ? "Envoi..." : "Envoyer mon avis"}
            </button>
          )}
        </div>

        <p style={{ fontSize: 11, color: C.mutedText, textAlign: "center", marginTop: 12, fontFamily: "Georgia, serif", opacity: 0.7 }}>Vos coordonnées restent confidentielles · OFI · Huile 100% bio</p>
      </div>
    </div>
  );
}

function StatCard({ label, value, accent }) {
  return (
    <div style={{ background: accent ? C.greenLight : C.cream, borderRadius: 10, padding: "1rem", textAlign: "center", border: `1px solid ${accent ? C.greenMid : C.sand}` }}>
      <div style={{ fontSize: 12, color: C.mutedText, marginBottom: 4, fontFamily: "Georgia, serif" }}>{label}</div>
      <div style={{ fontSize: 22, fontWeight: 500, color: accent ? C.green : C.darkText, fontFamily: "Georgia, serif" }}>{value}</div>
    </div>
  );
}

function BarChart({ data }) {
  const max = Math.max(...Object.values(data), 1);
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 8 }}>
      {Object.entries(data).sort((a, b) => b[1] - a[1]).map(([label, count]) => (
        <div key={label} style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <div style={{ fontSize: 12, color: C.mutedText, width: 130, flexShrink: 0, textAlign: "right", fontFamily: "Georgia, serif" }}>{label}</div>
          <div style={{ flex: 1, height: 16, background: C.cream, borderRadius: 4, overflow: "hidden", border: `1px solid ${C.sand}` }}>
            <div style={{ width: Math.round((count / max) * 100) + "%", height: "100%", background: `linear-gradient(90deg, ${C.greenMid}, ${C.gold})`, borderRadius: 4, transition: "width 0.5s" }} />
          </div>
          <div style={{ fontSize: 12, fontWeight: 500, width: 20, color: C.darkText, fontFamily: "Georgia, serif" }}>{count}</div>
        </div>
      ))}
    </div>
  );
}

function Dashboard({ responses, onLogout }) {
  const n = responses.length;
  if (n === 0) return (
    <div style={{ textAlign: "center", padding: "3rem" }}>
      <CactusIllustration size={80} opacity={0.3} />
      <h2 style={{ fontWeight: 400, marginBottom: 8, fontFamily: "Georgia, serif", color: C.darkText }}>Aucune réponse pour l'instant</h2>
      <p style={{ color: C.mutedText, fontSize: 14, fontFamily: "Georgia, serif" }}>Partagez le questionnaire avec vos testeurs.</p>
      <button onClick={onLogout} style={{ marginTop: 24, background: "transparent", border: `1px solid ${C.sand}`, borderRadius: 8, padding: "8px 20px", fontSize: 13, cursor: "pointer", fontFamily: "Georgia, serif", color: C.mutedText }}>Retour</button>
    </div>
  );

  function countOptions(qid) {
    const counts = {};
    responses.forEach(r => {
      const v = r[qid]; if (!v) return;
      (Array.isArray(v) ? v : [v]).forEach(x => { counts[x] = (counts[x] || 0) + 1; });
    });
    return counts;
  }

  function avgScale(qid) {
    const vals = responses.map(r => parseFloat(r[qid])).filter(v => !isNaN(v));
    if (!vals.length) return "–";
    return (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(1);
  }

  function npsScore() {
    const vals = responses.map(r => parseInt(r.q13)).filter(v => !isNaN(v));
    if (!vals.length) return "–";
    const p = vals.filter(v => v >= 9).length, d = vals.filter(v => v <= 6).length;
    return Math.round(((p - d) / vals.length) * 100);
  }

  const textResponses = qid => responses.map(r => r[qid]).filter(Boolean);

  return (
    <div style={{ padding: "1.5rem 0 2rem" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "1.5rem" }}>
        <div>
          <h1 style={{ fontSize: 20, fontWeight: 400, fontFamily: "Georgia, serif", color: C.darkText, marginBottom: 2 }}>Tableau de bord</h1>
          <p style={{ fontSize: 13, color: C.mutedText, fontFamily: "Georgia, serif" }}>OFI · Huile de figue de barbarie</p>
        </div>
        <button onClick={onLogout} style={{ background: "transparent", border: `1px solid ${C.sand}`, borderRadius: 8, padding: "6px 16px", fontSize: 13, cursor: "pointer", fontFamily: "Georgia, serif", color: C.mutedText }}>Déconnexion</button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: 10, marginBottom: "1.5rem" }}>
        <StatCard label="Réponses" value={n} accent />
        <StatCard label="Satisfaction" value={avgScale("q5") + "/5"} />
        <StatCard label="NPS" value={npsScore()} />
      </div>

      {[
        { id: "q1", label: "Profil des testeurs" },
        { id: "q2", label: "Gamme habituée" },
        { id: "q3", label: "Usage de l'huile" },
        { id: "q4", label: "Effets constatés" },
        { id: "q6", label: "Perception de l'odeur" },
        { id: "q7", label: "Préférence odeur" },
        { id: "q8", label: "Fragrance souhaitée" },
        { id: "q9", label: "Perception de la couleur" },
        { id: "q10", label: "Double filtration" },
        { id: "q11", label: "Prix acceptable (30ml)" },
        { id: "q12", label: "Intention de rachat" },
      ].map(({ id, label }) => (
        <div key={id} style={{ background: "white", border: `1px solid ${C.sand}`, borderRadius: 12, padding: "1rem 1.25rem", marginBottom: 10 }}>
          <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 2, color: C.darkText, fontFamily: "Georgia, serif" }}>{label}</div>
          <BarChart data={countOptions(id)} />
        </div>
      ))}

      {[{ id: "q14", label: "Ce qui a plu" }, { id: "q15", label: "Axes d'amélioration" }].map(({ id, label }) => {
        const texts = textResponses(id);
        if (!texts.length) return null;
        return (
          <div key={id} style={{ background: "white", border: `1px solid ${C.sand}`, borderRadius: 12, padding: "1rem 1.25rem", marginBottom: 10 }}>
            <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 10, color: C.darkText, fontFamily: "Georgia, serif" }}>{label} ({texts.length})</div>
            {texts.map((t, i) => (
              <div key={i} style={{ fontSize: 13, color: C.mutedText, padding: "6px 0", borderBottom: i < texts.length - 1 ? `1px solid ${C.sand}` : "none", fontFamily: "Georgia, serif", fontStyle: "italic" }}>"{t}"</div>
            ))}
          </div>
        );
      })}

      <div style={{ background: "white", border: `1px solid ${C.sand}`, borderRadius: 12, padding: "1rem 1.25rem", marginBottom: 10 }}>
        <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 12, color: C.darkText, fontFamily: "Georgia, serif" }}>Coordonnées des testeurs ({responses.filter(r => r.q16).length})</div>
        {responses.filter(r => r.q16 || r.q17 || r.q18).length === 0 ? (
          <div style={{ fontSize: 13, color: C.mutedText, fontFamily: "Georgia, serif", fontStyle: "italic" }}>Aucune coordonnée renseignée pour l'instant.</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {responses.filter(r => r.q16 || r.q17 || r.q18).map((r, i) => (
              <div key={i} style={{ padding: "8px 12px", background: C.cream, borderRadius: 8, border: `1px solid ${C.sand}` }}>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 16 }}>
                  {r.q16 && <span style={{ fontSize: 13, color: C.darkText, fontFamily: "Georgia, serif", fontWeight: 500 }}>{r.q16}</span>}
                  {r.q17 && <span style={{ fontSize: 13, color: C.mutedText, fontFamily: "Georgia, serif" }}>📞 {r.q17}</span>}
                  {r.q18 && <span style={{ fontSize: 13, color: C.green, fontFamily: "Georgia, serif" }}>✉ {r.q18}</span>}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ textAlign: "center", marginTop: "1.5rem" }}>
        <button onClick={() => {
          const csv = [Object.keys(responses[0]).join(","), ...responses.map(r => Object.values(r).map(v => `"${Array.isArray(v) ? v.join("|") : v || ""}"`).join(","))].join("\n");
          const blob = new Blob([csv], { type: "text/csv" });
          const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "ofi_reponses.csv"; a.click();
        }} style={{ background: C.green, border: "none", borderRadius: 10, padding: "11px 28px", fontSize: 14, fontWeight: 500, color: "white", cursor: "pointer", fontFamily: "Georgia, serif" }}>
          Exporter CSV
        </button>
      </div>
    </div>
  );
}

function LoginPanel({ onLogin }) {
  const [pw, setPw] = useState("");
  const [err, setErr] = useState(false);
  return (
    <div style={{ maxWidth: 340, margin: "3rem auto", textAlign: "center" }}>
      <div style={{ marginBottom: 20 }}><CactusIllustration size={70} opacity={0.5} /></div>
      <h2 style={{ fontSize: 18, fontWeight: 400, fontFamily: "Georgia, serif", color: C.darkText, marginBottom: 4 }}>Accès administrateur</h2>
      <p style={{ fontSize: 13, color: C.mutedText, marginBottom: 20, fontFamily: "Georgia, serif" }}>OFI · Tableau de bord</p>
      <input
        type="password"
        placeholder="Mot de passe"
        value={pw}
        onChange={e => { setPw(e.target.value); setErr(false); }}
        onKeyDown={e => e.key === "Enter" && (pw === ADMIN_PASSWORD ? onLogin() : setErr(true))}
        style={{ width: "100%", marginBottom: 8, borderRadius: 8, border: `1px solid ${err ? "#d97070" : C.sand}`, padding: "9px 14px", fontSize: 14, background: C.cream, color: C.darkText, outline: "none", boxSizing: "border-box", fontFamily: "Georgia, serif" }}
      />
      {err && <div style={{ fontSize: 12, color: "#c0392b", marginBottom: 8, fontFamily: "Georgia, serif" }}>Mot de passe incorrect</div>}
      <button onClick={() => pw === ADMIN_PASSWORD ? onLogin() : setErr(true)} style={{ background: C.green, border: "none", borderRadius: 10, padding: "11px 32px", fontSize: 14, color: "white", cursor: "pointer", width: "100%", fontFamily: "Georgia, serif" }}>
        Accéder
      </button>
    </div>
  );
}

export default function App() {
  const [view, setView] = useState("survey");
  const [responses, setResponses] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const raw = localStorage.getItem("ofi_responses");
        if (raw) setResponses(JSON.parse(raw));
      } catch {}
      setLoading(false);
    }
    load();
  }, []);

  async function handleSubmit(data) {
    const updated = [...responses, data];
    try { localStorage.setItem("ofi_responses", JSON.stringify(updated)); } catch {}
    setResponses(updated);
    try {
      await fetch("https://script.google.com/macros/s/AKfycbyoXELzIW3zMeZkcLBtZ3o2HWbUgxWFL0PwPw1WwkLRHweZDlohVEOMr8XJ9v1ph1Jx9A/exec", {
        method: "POST",
        mode: "no-cors",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...data, date: new Date().toLocaleString("fr-FR") })
      });
    } catch(err) { console.log("Sheet error", err); }
  }

  if (loading) return <div style={{ textAlign: "center", padding: "3rem", color: C.mutedText, fontSize: 14, fontFamily: "Georgia, serif" }}>Chargement...</div>;

  return (
    <div style={{ maxWidth: 620, margin: "0 auto", background: C.cream, minHeight: "100vh", fontFamily: "Georgia, serif" }}>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, padding: "0.6rem 1rem", borderBottom: `1px solid ${C.sand}` }}>
        <button onClick={() => setView("survey")} style={{ background: view === "survey" ? C.greenLight : "transparent", border: `1px solid ${view === "survey" ? C.greenMid : C.sand}`, borderRadius: 8, padding: "5px 14px", fontSize: 12, color: view === "survey" ? C.green : C.mutedText, cursor: "pointer", fontFamily: "Georgia, serif" }}>
          Questionnaire
        </button>
        <button onClick={() => setView(view === "admin" ? "survey" : "login")} style={{ background: view === "admin" ? C.greenLight : "transparent", border: `1px solid ${view === "admin" ? C.greenMid : C.sand}`, borderRadius: 8, padding: "5px 14px", fontSize: 12, color: view === "admin" ? C.green : C.mutedText, cursor: "pointer", fontFamily: "Georgia, serif" }}>
          Admin {responses.length > 0 ? `(${responses.length})` : ""}
        </button>
      </div>

      <div style={{ padding: "0 1rem" }}>
        {view === "survey" && <SurveyForm onSubmit={handleSubmit} />}
        {view === "login" && <LoginPanel onLogin={() => setView("admin")} />}
        {view === "admin" && <Dashboard responses={responses} onLogout={() => setView("survey")} />}
      </div>
    </div>
  );
}
